<script setup>import AppShell from'../../Layouts/AppShell.vue';import StateCard from'../../Components/StateCard.vue';import{Head,Link,useForm}from'@inertiajs/vue3';defineProps({event:Object,photos:Array,members:Array,invites:Array,indexRun:Object});const upload=useForm({photos:[]});</script><template><AppShell><Head :title="event.name"/><section class="overflow-hidden rounded-2xl bg-ink text-white"><div class="bg-gradient-to-r from-indigo/70 via-transparent to-coral/20 p-7 md:p-10"><p class="text-xs font-bold uppercase tracking-[.18em] text-white/55">Event workspace</p><h1 class="mt-3 font-display text-3xl font-bold md:text-4xl">{{event.name}}</h1><p class="mt-3 text-sm text-white/55">{{event.location||'Private event'}} · {{event.privacy}}</p></div></section><div class="mt-6 grid gap-6 xl:grid-cols-[1fr_320px]"><div><div class="panel p-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-display text-xl font-bold">Upload & processing</h2><p class="mt-1 text-sm text-black/45">New files enter the durable private-media queue.</p></div><label class="btn-primary cursor-pointer">Choose photos<input type="file" multiple accept="image/*" class="hidden" @change="upload.photos=[...$event.target.files]"></label></div><div v-if="upload.photos.length" class="mt-5 rounded-xl bg-indigo/5 p-4"><p class="font-semibold">{{upload.photos.length}} files ready</p><button class="btn-primary mt-3" @click="upload.post(`/groups/${event.id}/photos`)">Start upload</button></div></div><h2 class="mt-8 font-display text-xl font-bold">Gallery</h2><StateCard v-if="!photos.length" class="mt-4" title="No photographs yet" message="Upload event photos to begin private processing and face indexing."/><div v-else class="photo-grid mt-4 grid grid-cols-2 gap-1 md:grid-cols-3 xl:grid-cols-4"><Link v-for="p in photos" :key="p.id" :href="`/groups/${event.id}/photos/${p.id}`" class="aspect-[4/3] overflow-hidden bg-black/10"><img :src="p.url" :alt="p.original_filename" class="h-full w-full object-cover"></Link></div></div><aside class="space-y-5"><div class="panel p-5"><h3 class="font-display font-bold">Participants</h3><p class="mt-2 text-3xl font-bold">{{members.length}}</p><Link :href="`/groups/${event.id}/members`" class="btn-muted mt-4 w-full">Manage permissions</Link></div><div class="panel p-5"><h3 class="font-display font-bold">Invitation access</h3><div v-for="i in invites" :key="i.id" class="mt-3 rounded-xl bg-black/[.03] p-3"><p class="text-sm font-semibold">{{i.label}}</p><p class="mt-1 font-mono text-xs text-indigo">{{i.access_code}}</p></div></div><div class="panel p-5"><h3 class="font-display font-bold">Face indexing</h3><p class="mt-2 text-sm text-black/50">{{indexRun?.state||'Not started'}}</p><Link :href="`/groups/${event.id}/operations`" class="btn-secondary mt-4 w-full">Processing & exports</Link><Link :href="`/groups/${event.id}/face-reviews`" class="btn-secondary mt-2 w-full">Manual review</Link></div></aside></div></AppShell></template>
